class Hotel:
    def __init__(self, name, rooms):
        self.name = name
        self.available_rooms = rooms
        # available_rooms = {room_type1: room_number1, room_type2: room_number2, ...}
        # available_rooms = {'single': 5, 'double': 3}
        self.booked_rooms = {}
        # booked_rooms = {room_type1: {name1: room_number1, name2: room_number2, ...}, room_type2: {...}, ...}
        # booked_rooms = {'single': {'name1': 2, 'name2':1}, 'double': {}}

    def book_room(self, room_type, room_number, name):
        # Check if there are any rooms of the specified type available
        if not self._has_room_type(room_type):
            return False

        if self._is_room_available(room_type, room_number):
            self._book_room_internal(room_type, name, room_number)
            return "Success!"
        elif self.available_rooms[room_type] != 0:
            return self.available_rooms[room_type]
        else:
            return False

    def check_in(self, room_type, room_number, name):
        # Check if the room of the specified type and number is booked
        if not self._is_room_type_booked(room_type):
            return False

        if name in self.booked_rooms[room_type]:
            booked_count = self.booked_rooms[room_type][name]
            if room_number > booked_count:
                return False
            elif room_number == booked_count:
                self._check_in_room(room_type, name)
            else:
                self._check_in_partial(room_type, name, room_number)

    def check_out(self, room_type, room_number):
        if room_type in self.available_rooms:
            self._add_available_room(room_type, room_number)
        else:
            self._set_available_room(room_type, room_number)

    def get_available_rooms(self, room_type):
        return self._get_available_rooms_internal(room_type)

    def _has_room_type(self, room_type):
        return room_type in self.available_rooms.keys()

    def _is_room_available(self, room_type, room_number):
        return room_number <= self.available_rooms[room_type]

    def _book_room_internal(self, room_type, name, room_number):
        if room_type not in self.booked_rooms.keys():
            self.booked_rooms[room_type] = {}
        self.booked_rooms[room_type][name] = room_number
        self.available_rooms[room_type] -= room_number

    def _is_room_type_booked(self, room_type):
        return room_type in self.booked_rooms.keys()

    def _check_in_room(self, room_type, name):
        self.booked_rooms[room_type].pop(name)

    def _check_in_partial(self, room_type, name, room_number):
        self.booked_rooms[room_type][name] -= room_number

    def _add_available_room(self, room_type, room_number):
        self.available_rooms[room_type] += room_number

    def _set_available_room(self, room_type, room_number):
        self.available_rooms[room_type] = room_number

    def _get_available_rooms_internal(self, room_type):
        return self.available_rooms[room_type]
